package com.reviewflow.web;
import com.reviewflow.domain.User; import com.reviewflow.repo.UserRepository; import com.reviewflow.security.JwtService; import jakarta.validation.constraints.*; import org.springframework.http.*; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/auth") public class AuthController { private final UserRepository users;private final PasswordEncoder passwords;private final JwtService jwt;public AuthController(UserRepository u,PasswordEncoder p,JwtService j){users=u;passwords=p;jwt=j;}record Register(@NotBlank String ownerName,@NotBlank String businessName,@Email String email,@Size(min=8) String password){}record Login(@Email String email,@NotBlank String password){} record AuthResponse(String token,String ownerName,String businessName){}
 @PostMapping("/register") public ResponseEntity<AuthResponse> register(@RequestBody @jakarta.validation.Valid Register in){if(users.findByEmailIgnoreCase(in.email()).isPresent())throw new org.springframework.web.server.ResponseStatusException(HttpStatus.CONFLICT,"An account with that email already exists.");User u=new User();u.name=in.ownerName();u.email=in.email().toLowerCase();u.passwordHash=passwords.encode(in.password());users.save(u);return ResponseEntity.status(HttpStatus.CREATED).body(new AuthResponse(jwt.issue(u.id),u.name,in.businessName));}
 @PostMapping("/login") public AuthResponse login(@RequestBody @jakarta.validation.Valid Login in){User u=users.findByEmailIgnoreCase(in.email()).filter(x->passwords.matches(in.password(),x.passwordHash)).orElseThrow(()->new org.springframework.web.server.ResponseStatusException(HttpStatus.UNAUTHORIZED,"Invalid email or password."));return new AuthResponse(jwt.issue(u.id),u.name,null);}
 record ChangePassword(@NotBlank String currentPassword,@Size(min=8) String newPassword){}
 @PostMapping("/change-password") public ResponseEntity<Void> changePassword(@RequestBody @jakarta.validation.Valid ChangePassword in,org.springframework.security.core.Authentication auth){User u=users.findById((UUID)auth.getPrincipal()).orElseThrow(()->new org.springframework.web.server.ResponseStatusException(HttpStatus.UNAUTHORIZED));if(!passwords.matches(in.currentPassword(),u.passwordHash))throw new org.springframework.web.server.ResponseStatusException(HttpStatus.BAD_REQUEST,"Current password is incorrect.");u.passwordHash=passwords.encode(in.newPassword());users.save(u);return ResponseEntity.noContent().build();}
 @PostMapping("/forgot-password") public ResponseEntity<Void> forgot(@RequestBody Map<String,String> body){return ResponseEntity.accepted().build();} }
